typedef struct {
    int *data;
    int size;
    int capacity;
} Vec;

Vec *vec_new(void) {
    Vec *v = (Vec *)malloc(sizeof(Vec));
    v->data = NULL;
    v->size = 0;
    v->capacity = 0;
    return v;
}

void vec_push(Vec *v, int value) {
    if (v->size == v->capacity) {
        int new_cap = v->capacity == 0 ? 4 : v->capacity * 2;
        int *new_data = (int *)realloc(v->data, new_cap * sizeof(int));
        v->data = new_data;
        v->capacity = new_cap;
    }
    v->data[v->size++] = value;
}

int main(void) {
    Vec *v = vec_new();
    vec_push(v, 10);
    vec_push(v, 20);
    vec_push(v, 30);
    printf("%d %d\n", v->size, v->data[0]);
    return 0;
}

