/* Minimal JSON handling for this specific task.
   We build {"count":12}, serialize, then parse to extract count. */

static int parse_count(const char *json, long *out) {
    /* Find "count" key */
    const char *p = strstr(json, "\"count\"");
    if (!p) return 0;
    p += strlen("\"count\"");
    /* skip whitespace and colon */
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    if (*p != ':') return 0;
    p++;
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    /* parse integer */
    char *end;
    long v = strtol(p, &end, 10);
    if (end == p) return 0;
    *out = v;
    return 1;
}

int main(void) {
    /* Build JSON object with key "count" set to integer 12 */
    char json[64];
    snprintf(json, sizeof(json), "{\"count\":%d}", 12);

    /* Serialize (json is already the serialized string) */
    /* Parse it back */
    long count = 0;
    if (!parse_count(json, &count)) {
        return 1;
    }

    printf("%ld\n", count);
    return 0;
}

